// Chuyển ảnh Telegram sang base64 + dựng body gọi Gemini
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');
const bin = $input.item.binary && $input.item.binary.data ? $input.item.binary.data : {};
const mimeType = bin.mimeType || 'image/jpeg';
const tg = $('Telegram: nhận phiếu').item.json;
const msg = tg.message || {};
const fileName = bin.fileName || ('telegram_' + (msg.message_id || Date.now()) + '.jpg');
const prompt = "Bạn là trợ lý kế toán đọc PHIẾU CÂN của nhà máy xay xát gạo Thạnh Hương. Ảnh có thể là phiếu IN hoặc phiếu VIẾT TAY (ghi tay, tính toán tay). Hãy đọc thật kỹ, kể cả chữ viết tay và các phép tính, rồi trích xuất thông tin.\n\nCHỈ TRẢ VỀ 1 object JSON đúng cấu trúc sau (không thêm giải thích):\n{\n  \"ngay\": \"ngày trên phiếu, dạng DD/MM/YYYY nếu đọc được\",\n  \"so_phieu\": \"số phiếu/chứng từ nếu có\",\n  \"nguoi_ban_khach_hang\": \"tên người bán/khách hàng/nhà cung cấp nếu có\",\n  \"loai_hang_lua\": \"loại hàng hoặc loại lúa (vd: lúa tươi, OM5451, cám gạo, trấu, tấm...)\",\n  \"so_xe\": \"biển số xe nếu có\",\n  \"tl_xe_vao\": \"trọng lượng xe vào/xe có hàng, CHỈ số kg\",\n  \"tl_xe_ra\": \"trọng lượng xe ra/xe không, CHỈ số kg\",\n  \"tl_hang\": \"trọng lượng hàng (tịnh), CHỈ số kg\",\n  \"do_am\": \"độ ẩm % nếu có\",\n  \"kieu_can\": \"NHẬP hay XUẤT nếu xác định được\",\n  \"ghi_chu_chat_luong\": \"ghi chú chất lượng/tạp chất/đơn giá/thành tiền nếu có\",\n  \"nguoi_can\": \"tên người cân/người ghi nếu có\",\n  \"do_tin_cay\": \"cao | trung bình | thấp — mức chắc chắn khi đọc, hạ thấp nếu chữ tay khó\",\n  \"can_kiem_tra\": true hoặc false — true nếu có trường quan trọng (số cân/người bán/loại lúa) không chắc,\n  \"ly_do_kiem_tra\": \"vì sao cần kiểm tra, rỗng nếu không\"\n}\nTrường nào không có thì để chuỗi rỗng. Số cân chỉ ghi con số, không kèm 'kg', không dấu phẩy ngăn nghìn.";
return {
  json: {
    fileName,
    chatId: (msg.chat && msg.chat.id) || '',
    messageId: msg.message_id || '',
    body: {
      contents: [{ parts: [ { text: prompt }, { inline_data: { mime_type: mimeType, data: base64 } } ] }],
      generationConfig: { temperature: 0, response_mime_type: 'application/json' }
    }
  },
  binary: $input.item.binary
};

// Phân tích kết quả Gemini + kiểm tra logic số cân
const prep = $('Chuẩn bị ảnh (Gemini)').item.json;
const fileName = prep.fileName;
let driveId = '';
try { driveId = $('Lưu ảnh vào Drive').item.json.id; } catch (e) { driveId = ''; }
const linkAnh = driveId ? ('https://drive.google.com/file/d/' + driveId + '/view') : ('telegram-msg-' + (prep.messageId || ''));

let text = '';
try { text = $json.candidates[0].content.parts[0].text; } catch (e) { text = ''; }
let clean = (text || '').trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
let data = {}; let parseError = '';
try { data = JSON.parse(clean); } catch (e) { parseError = 'Không đọc được JSON từ AI'; data = {}; }

const toNum = (s) => { if (s === null || s === undefined || s === '') return null; const n = Number(String(s).replace(/[^0-9.\-]/g, '')); return isNaN(n) ? null : n; };
const vao = toNum(data.tl_xe_vao), ra = toNum(data.tl_xe_ra); let hang = toNum(data.tl_hang);
if (hang === null && vao !== null && ra !== null) hang = Math.abs(vao - ra);

let mathOk = true, mathNote = '';
if (vao !== null && ra !== null && hang !== null) {
  const diff = Math.abs(Math.abs(vao - ra) - hang);
  if (diff > Math.max(20, hang * 0.01)) { mathOk = false; mathNote = 'Lệch cân: |'+vao+'-'+ra+'| khác '+hang; }
}

const conf = String(data.do_tin_cay || '').toLowerCase();
const lowConf = conf.includes('thấp') || conf.includes('thap') || conf === 'low';
const aiFlag = data.can_kiem_tra === true || data.can_kiem_tra === 'true';
const needsReview = !!(parseError || lowConf || !mathOk || aiFlag);

const reasons = [];
if (parseError) reasons.push(parseError);
if (lowConf) reasons.push('AI báo độ tin cậy thấp');
if (!mathOk) reasons.push(mathNote);
if (aiFlag && data.ly_do_kiem_tra) reasons.push(data.ly_do_kiem_tra);
else if (aiFlag) reasons.push('AI đánh dấu cần kiểm tra');

return { json: {
  'Thời gian xử lý': new Date().toISOString(),
  'Tên file': fileName || '',
  'Link ảnh': linkAnh,
  'Ngày phiếu': data.ngay || '',
  'Số phiếu': data.so_phieu || '',
  'Người bán / Khách hàng': data.nguoi_ban_khach_hang || '',
  'Loại hàng / lúa': data.loai_hang_lua || '',
  'Số xe': data.so_xe || '',
  'TL xe vào (kg)': vao !== null ? vao : '',
  'TL xe ra (kg)': ra !== null ? ra : '',
  'TL hàng (kg)': hang !== null ? hang : '',
  'Độ ẩm (%)': data.do_am || '',
  'Kiểu cân': data.kieu_can || '',
  'Ghi chú chất lượng': data.ghi_chu_chat_luong || '',
  'Người cân': data.nguoi_can || '',
  'Độ tin cậy': data.do_tin_cay || '',
  'Cần kiểm tra': needsReview ? 'CÓ' : 'Không',
  'Lý do kiểm tra': reasons.join('; ')
} };

